const priorities = new Map([
  ['critical', 0],
  ['high', 1],
  ['normal', 2],
  ['low', 3],
]);

export function rankTickets(items) {
  return items
    .map((item, index) => ({
      item,
      index,
      closed: item.status === 'closed' ? 1 : 0,
      priority: priorities.get(item.priority) ?? priorities.size,
      due: Number.isFinite(item.due) ? item.due : Infinity,
    }))
    .sort((a, b) =>
      a.closed - b.closed ||
      a.priority - b.priority ||
      (a.due < b.due ? -1 : a.due > b.due ? 1 : 0) ||
      a.index - b.index
    )
    .map(({ item }) => item);
}

