import assert from 'node:assert/strict';
import test from 'node:test';
import { rankTickets } from './rank.mjs';

const ids = (items) => rankTickets(items).map(({ id }) => id);

test('status, priority, and due are applied in that order', () => {
  const items = [
    { id: 'closed-critical', status: 'closed', priority: 'critical', due: -100 },
    { id: 'open-unknown', status: 'open', priority: 'urgent', due: -100 },
    { id: 'open-low', status: 'open', priority: 'low', due: -100 },
    { id: 'open-normal', status: 'open', priority: 'normal', due: -100 },
    { id: 'high-late', status: 'open', priority: 'high', due: 10 },
    { id: 'critical-missing', status: 'open', priority: 'critical' },
    { id: 'high-early', status: 'open', priority: 'high', due: 0 },
    { id: 'closed-low', status: 'closed', priority: 'low', due: -200 },
    { id: 'critical-valid', status: 'open', priority: 'critical', due: 100 },
  ];
  assert.deepEqual(ids(items), [
    'critical-valid', 'critical-missing', 'high-early', 'high-late',
    'open-normal', 'open-low', 'open-unknown', 'closed-critical', 'closed-low',
  ]);
});

test('only the exact string closed counts as closed', () => {
  const statuses = ['open', 'Closed', 'CLOSED', 'closed ', '', undefined,
    null, false, 0, {}, new String('closed')];
  const open = statuses.map((status, id) => ({ id, status }));
  assert.deepEqual(ids([{ id: 'closed', status: 'closed' }, ...open]),
    [...open.map(({ id }) => id), 'closed']);
});

test('all unknown priorities follow known priorities and tie with each other', () => {
  const unknown = ['urgent', 'HIGH', 'constructor', 'toString', '__proto__',
    '', undefined, null, 0, {}, Symbol('critical'), new String('high')]
    .map((priority, id) => ({ id, priority, due: 0 }));
  const known = ['low', 'normal', 'high', 'critical']
    .map((priority) => ({ id: priority, priority, due: 100 }));
  assert.deepEqual(ids([...unknown, ...known]),
    ['critical', 'high', 'normal', 'low', ...unknown.map(({ id }) => id)]);
  assert.deepEqual(ids([
    { id: 'later', priority: 'urgent', due: 2 },
    { id: 'earlier', priority: 'other', due: 1 },
  ]), ['earlier', 'later']);
});

test('finite numeric due dates sort ascending, including zero and negatives', () => {
  const values = [Number.MAX_VALUE, 0, 1.5, -2, -Number.MAX_VALUE, 0.25];
  assert.deepEqual(rankTickets(values.map((due) => ({ due }))).map(x => x.due),
    [-Number.MAX_VALUE, -2, 0, 0.25, 1.5, Number.MAX_VALUE]);
});

test('invalid and missing due dates come last without coercion, in original order', () => {
  const coercible = { valueOf() { throw new Error('must not coerce due'); } };
  const invalid = [NaN, Infinity, -Infinity, '0', '-100', '', null, undefined,
    false, true, [], [0], {}, new Number(0), new Date(0), 0n, Symbol('due'), coercible]
    .map((due, id) => ({ id, due }));
  invalid.splice(3, 0, { id: 'missing' });
  const items = [...invalid.slice(0, 5), { id: 'valid-positive', due: 10 },
    ...invalid.slice(5), { id: 'valid-zero', due: 0 }];
  assert.deepEqual(ids(items),
    ['valid-zero', 'valid-positive', ...invalid.map(({ id }) => id)]);
});

test('equal sort keys preserve original order across interleaved groups', () => {
  const items = [
    { id: 'closed-a', status: 'closed', priority: 'high', due: 0 },
    { id: 'open-a', status: 'pending', priority: 'normal', due: -0 },
    { id: 'critical', priority: 'critical' },
    { id: 'open-b', status: 'open', priority: 'normal', due: 0 },
    { id: 'closed-b', status: 'closed', priority: 'high', due: -0 },
    { id: 'open-c', priority: 'normal', due: 0 },
  ];
  assert.deepEqual(ids(items),
    ['critical', 'open-a', 'open-b', 'open-c', 'closed-a', 'closed-b']);
});

test('returns a new array without changing the input or ticket objects', () => {
  const later = Object.freeze({ id: 'later', priority: 'low', due: 2 });
  const earlier = Object.freeze({ id: 'earlier', priority: 'high', due: 1 });
  const items = Object.freeze([later, earlier, later]);
  const result = rankTickets(items);
  assert.notStrictEqual(result, items);
  assert.deepEqual(items, [later, earlier, later]);
  assert.strictEqual(result[0], earlier);
  assert.strictEqual(result[1], later);
  assert.strictEqual(result[2], later);
});

test('empty and single-item inputs return distinct arrays', () => {
  const empty = Object.freeze([]);
  const result = rankTickets(empty);
  assert.deepEqual(result, []);
  assert.notStrictEqual(result, empty);
  const ticket = Object.freeze({});
  const single = Object.freeze([ticket]);
  const ranked = rankTickets(single);
  assert.notStrictEqual(ranked, single);
  assert.strictEqual(ranked[0], ticket);
});

