import test from 'node:test';
import assert from 'node:assert/strict';
import { rankTickets } from './rank.mjs';

test('status, priority, and due are applied in that order', () => {
  const tickets = [
    { id: 'closed-critical', status: 'closed', priority: 'critical', due: -100 },
    { id: 'unknown', priority: 'urgent', due: -100 },
    { id: 'low', priority: 'low', due: -100 },
    { id: 'normal', priority: 'normal', due: -100 },
    { id: 'high-late', priority: 'high', due: 20 },
    { id: 'high-early', priority: 'high', due: 10 },
    { id: 'critical', priority: 'critical', due: 100 },
    { id: 'closed-low', status: 'closed', priority: 'low', due: -200 },
  ];
  assert.deepEqual(rankTickets(tickets).map(t => t.id), [
    'critical', 'high-early', 'high-late', 'normal', 'low', 'unknown',
    'closed-critical', 'closed-low',
  ]);
});

test('only the exact status closed is closed; other statuses tie stably', () => {
  const tickets = ['closed', 'Closed', undefined, null, '', false, 'open']
    .map(status => ({ status }));
  assert.deepEqual(rankTickets(tickets), [...tickets.slice(1), tickets[0]]);
});

test('unknown priorities sort last without coercion and retain original order', () => {
  const unknown = [undefined, null, 'HIGH', 'toString', '__proto__', 0, {}, Symbol('high')]
    .map(priority => ({ priority }));
  const known = ['low', 'normal', 'high', 'critical'].map(priority => ({ priority }));
  assert.deepEqual(rankTickets([...unknown, ...known]), [...known.reverse(), ...unknown]);
});

test('finite numeric due dates include zero and negatives; invalid dates stay last stably', () => {
  const invalid = [undefined, null, NaN, Infinity, -Infinity, '', '1', false, true,
    new Number(1), {}, [], 1n, Symbol('due')].map(due => ({ due }));
  const finite = [Number.MAX_VALUE, 0, -5, 2.5, -Number.MAX_VALUE].map(due => ({ due }));
  assert.deepEqual(rankTickets([...invalid, ...finite]), [
    finite[4], finite[2], finite[1], finite[3], finite[0], ...invalid,
  ]);
});

test('equal keys preserve original order, including missing and invalid due dates', () => {
  const a = { priority: 'high', due: 0 };
  const b = { priority: 'high', due: -0 };
  const c = { priority: 'low' };
  const d = { priority: 'low', due: NaN };
  assert.deepEqual(rankTickets([c, a, d, b, a]), [a, b, a, c, d]);
});

test('returns a new array without mutating frozen input or replacing ticket objects', () => {
  const late = Object.freeze({ due: 10, details: Object.freeze({ label: 'late' }) });
  const early = Object.freeze({ due: 0 });
  const input = Object.freeze([late, early]);
  const result = rankTickets(input);
  assert.notStrictEqual(result, input);
  assert.strictEqual(result[0], early);
  assert.strictEqual(result[1], late);
  assert.deepEqual(input, [late, early]);
});

test('empty and singleton inputs return new arrays', () => {
  const empty = Object.freeze([]);
  assert.deepEqual(rankTickets(empty), []);
  assert.notStrictEqual(rankTickets(empty), empty);
  const single = Object.freeze([Object.freeze({})]);
  assert.deepEqual(rankTickets(single), single);
  assert.notStrictEqual(rankTickets(single), single);
});

