function normalize(intervals) {
  const sorted = [];
  for (const [start, end] of intervals) {
    if (!Number.isInteger(start) || !Number.isInteger(end) || start > end) {
      throw new RangeError('Interval endpoints must be finite integers with start <= end');
    }
    if (start < end) sorted.push([start, end]);
  }
  sorted.sort((a, b) => a[0] - b[0]);

  const union = [];
  for (const interval of sorted) {
    const last = union[union.length - 1];
    if (last && interval[0] <= last[1]) {
      last[1] = Math.max(last[1], interval[1]);
    } else {
      union.push(interval);
    }
  }
  return union;
}

export function subtractIntervals(base, removed) {
  const bases = normalize(base);
  const removals = normalize(removed);
  const result = [];
  let index = 0;

  for (const [start, end] of bases) {
    let cursor = start;
    while (index < removals.length && removals[index][1] <= cursor) index++;
    while (index < removals.length && removals[index][0] < end) {
      const [cutStart, cutEnd] = removals[index];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      // Keep a removal that may also overlap the next base interval.
      if (cursor >= end) break;
      index++;
    }
    if (cursor < end) result.push([cursor, end]);
  }
  return result;
}

