import test from 'node:test';
import assert from 'node:assert/strict';
import { subtractIntervals } from './ranges.mjs';

const cases = [
  ['empty sets', [], [], []],
  ['empty base', [], [[1, 5]], []],
  ['no removals', [[1, 5]], [], [[1, 5]]],
  ['interior split', [[0, 10]], [[3, 7]], [[0, 3], [7, 10]]],
  ['left overlap', [[0, 10]], [[-2, 4]], [[4, 10]]],
  ['right overlap', [[0, 10]], [[6, 12]], [[0, 6]]],
  ['full coverage', [[0, 10]], [[-1, 11]], []],
  ['equal intervals', [[0, 10]], [[0, 10]], []],
  ['touching boundaries', [[0, 10]], [[-3, 0], [10, 12]], [[0, 10]]],
  ['matching left boundary', [[0, 10]], [[0, 4]], [[4, 10]]],
  ['matching right boundary', [[0, 10]], [[6, 10]], [[0, 6]]],
  ['multiple cuts', [[0, 10]], [[7, 9], [1, 3]], [[0, 1], [3, 7], [9, 10]]],
  ['spanning removal', [[0, 2], [4, 6], [8, 10]], [[1, 9]], [[0, 1], [9, 10]]],
  ['removals in gaps', [[0, 2], [8, 10]], [[3, 7]], [[0, 2], [8, 10]]],
  ['normalize base', [[6, 8], [2, 5], [0, 3], [5, 6], [2, 5]], [], [[0, 8]]],
  ['normalize removed', [[0, 12]], [[6, 8], [2, 5], [4, 6], [2, 5]], [[0, 2], [8, 12]]],
  ['nested intervals', [[0, 10], [2, 3]], [[2, 8], [3, 4]], [[0, 2], [8, 10]]],
  ['zero lengths', [[2, 2], [0, 5]], [[3, 3], [9, 9]], [[0, 5]]],
  ['only zero lengths', [[2, 2]], [[3, 3]], []],
  ['negative endpoints', [[-10, -2]], [[-8, -5]], [[-10, -8], [-5, -2]]],
];

for (const [name, base, removed, expected] of cases) {
  test(name, () => {
    const before = structuredClone([base, removed]);
    base.forEach(Object.freeze);
    removed.forEach(Object.freeze);
    Object.freeze(base);
    Object.freeze(removed);
    const actual = subtractIntervals(base, removed);
    assert.deepEqual(actual, expected);
    assert.deepEqual([base, removed], before);
    if (actual.length) actual[0][0] = 999;
    assert.deepEqual([base, removed], before, 'output must not alias inputs');
  });
}

test('invalid endpoints and inverted intervals in either input throw RangeError', () => {
  const invalid = [
    [2, 1], [0.5, 1], [0, 1.5], [NaN, 2], [0, NaN],
    [-Infinity, 2], [0, Infinity], [Infinity, Infinity],
    [-Infinity, -Infinity], [0.5, 0.5], ['0', 2], [0, '2'],
    [null, 2], [0, undefined],
  ];
  for (const interval of invalid) {
    for (const valid of [[], [[0, 10]]]) {
      assert.throws(() => subtractIntervals([interval], valid), RangeError);
      assert.throws(() => subtractIntervals(valid, [interval]), RangeError);
    }
  }
  assert.throws(() => subtractIntervals([[0, 10], [3, 2]], []), RangeError);
  assert.throws(() => subtractIntervals([], [[0, 10], [3, 2]]), RangeError);
});

test('deterministic generated cases agree with an integer-cell oracle', () => {
  let seed = 12345;
  const random = n => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % n;
  };
  const generate = () => Array.from({ length: random(9) }, () => {
    const a = random(21) - 10;
    const b = random(21) - 10;
    return [Math.min(a, b), Math.max(a, b)];
  });
  const contains = (intervals, x) => intervals.some(([a, b]) => a <= x && x < b);
  for (let trial = 0; trial < 1000; trial++) {
    const base = generate();
    const removed = generate();
    const expected = [];
    for (let x = -10; x < 10; x++) {
      if (contains(base, x) && !contains(removed, x)) {
        const last = expected.at(-1);
        if (last && last[1] === x) last[1] = x + 1;
        else expected.push([x, x + 1]);
      }
    }
    assert.deepEqual(subtractIntervals(base, removed), expected, `trial ${trial}`);
  }
});

