function normalize(intervals) {
  const sorted = [];
  for (const [start, end] of intervals) {
    if (!Number.isInteger(start) || !Number.isInteger(end) || start > end) {
      throw new RangeError('Interval endpoints must be finite integers with start <= end');
    }
    if (start < end) sorted.push([start, end]);
  }
  sorted.sort((a, b) => a[0] - b[0]);

  const union = [];
  for (const interval of sorted) {
    const previous = union[union.length - 1];
    if (previous && interval[0] <= previous[1]) {
      previous[1] = Math.max(previous[1], interval[1]);
    } else {
      union.push(interval);
    }
  }
  return union;
}

export function subtractIntervals(base, removed) {
  // Normalize both inputs before subtracting so even unused intervals are validated.
  const sources = normalize(base);
  const cuts = normalize(removed);
  const result = [];
  let cutIndex = 0;

  for (const [start, end] of sources) {
    let cursor = start;
    while (cutIndex < cuts.length && cuts[cutIndex][1] <= cursor) cutIndex++;

    while (cutIndex < cuts.length && cuts[cutIndex][0] < end) {
      const [cutStart, cutEnd] = cuts[cutIndex];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      // Keep this cut available if it also covers subsequent base intervals.
      if (cursor >= end) break;
      cutIndex++;
    }
    if (cursor < end) result.push([cursor, end]);
  }
  return result;
}

