import test from 'node:test';
import assert from 'node:assert/strict';
import { subtractIntervals } from './ranges.mjs';

const cases = [
  ['empty sets', [], [], []],
  ['empty base', [], [[1, 5]], []],
  ['empty removals', [[1, 5]], [], [[1, 5]]],
  ['interior split', [[0, 10]], [[3, 7]], [[0, 3], [7, 10]]],
  ['left overlap', [[0, 10]], [[-3, 4]], [[4, 10]]],
  ['right overlap', [[0, 10]], [[6, 14]], [[0, 6]]],
  ['exact removal', [[0, 10]], [[0, 10]], []],
  ['containing removal', [[0, 10]], [[-1, 11]], []],
  ['touching boundaries', [[0, 10]], [[-5, 0], [10, 15]], [[0, 10]]],
  ['disjoint removals', [[0, 10]], [[-5, -1], [11, 15]], [[0, 10]]],
  ['multiple splits', [[0, 10]], [[6, 8], [2, 4]], [[0, 2], [4, 6], [8, 10]]],
  ['base union', [[8, 10], [2, 6], [0, 3], [6, 8], [2, 6], [1, 2]], [], [[0, 10]]],
  ['removed union', [[0, 12]], [[6, 9], [2, 5], [4, 6], [3, 4], [2, 5]], [[0, 2], [9, 12]]],
  ['both unions', [[5, 10], [0, 6]], [[7, 9], [2, 4], [4, 7]], [[0, 2], [9, 10]]],
  ['one cut spanning bases', [[0, 3], [5, 7], [9, 12]], [[2, 10]], [[0, 2], [10, 12]]],
  ['cut ends at later base start', [[0, 3], [5, 7]], [[2, 5]], [[0, 2], [5, 7]]],
  ['cut in base gap', [[0, 2], [5, 7]], [[3, 4]], [[0, 2], [5, 7]]],
  ['zero lengths ignored', [[1, 1], [0, 5], [8, 8]], [[2, 2], [0, 0], [5, 5]], [[0, 5]]],
  ['only zero lengths', [[-1, -1]], [[0, 0]], []],
  ['negative endpoints', [[-10, -2], [-4, 3]], [[-6, -3], [0, 2]], [[-10, -6], [-3, 0], [2, 3]]],
  ['large finite integers', [[-Number.MAX_VALUE, Number.MAX_VALUE]], [[-1, 1]],
    [[-Number.MAX_VALUE, -1], [1, Number.MAX_VALUE]]],
];

for (const [name, base, removed, expected] of cases) {
  test(name, () => assert.deepEqual(subtractIntervals(base, removed), expected));
}

test('rejects invalid endpoints in either set, including when the other set is empty', () => {
  const invalidEndpoints = [NaN, Infinity, -Infinity, 0.5, -0.5, '1', null, undefined, true, 1n];
  const invalidIntervals = [[2, 1]];
  for (const endpoint of invalidEndpoints) {
    invalidIntervals.push([endpoint, 2], [-2, endpoint], [endpoint, endpoint]);
  }
  for (const invalid of invalidIntervals) {
    assert.throws(() => subtractIntervals([invalid], []), RangeError);
    assert.throws(() => subtractIntervals([], [invalid]), RangeError);
    assert.throws(() => subtractIntervals([[0, 10], invalid], [[-20, 20]]), RangeError);
    assert.throws(() => subtractIntervals([[0, 10]], [[-20, 20], invalid]), RangeError);
  }
});

test('does not mutate inputs or return aliases to their intervals', () => {
  const base = Object.freeze([Object.freeze([5, 10]), Object.freeze([0, 6])]);
  const removed = Object.freeze([Object.freeze([8, 9]), Object.freeze([2, 3])]);
  const result = subtractIntervals(base, removed);
  assert.deepEqual(result, [[0, 2], [3, 8], [9, 10]]);
  result[0][0] = -100;
  assert.deepEqual(base, [[5, 10], [0, 6]]);
  assert.deepEqual(removed, [[8, 9], [2, 3]]);

  const untouched = subtractIntervals(base, []);
  untouched[0][1] = 100;
  assert.deepEqual(base, [[5, 10], [0, 6]]);
});

// Independent oracle: represent small integer intervals as occupied unit cells.
function unitCells(intervals) {
  const cells = new Set();
  for (const [start, end] of intervals) {
    for (let i = start; i < end; i++) cells.add(i);
  }
  return cells;
}

test('matches a unit-cell oracle across 1,000 deterministic input pairs', () => {
  let seed = 123456789;
  const random = (limit) => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % limit;
  };
  const intervals = () => Array.from({ length: random(9) }, () => {
    const a = random(21) - 10;
    const b = random(21) - 10;
    return [Math.min(a, b), Math.max(a, b)];
  });

  for (let trial = 0; trial < 1000; trial++) {
    const base = intervals();
    const removed = intervals();
    const snapshot = structuredClone([base, removed]);
    const expected = unitCells(base);
    for (const cell of unitCells(removed)) expected.delete(cell);
    const actual = subtractIntervals(base, removed);
    assert.deepEqual(unitCells(actual), expected, `trial ${trial}`);
    assert.deepEqual([base, removed], snapshot);
    for (let i = 0; i < actual.length; i++) {
      const [start, end] = actual[i];
      assert.ok(Number.isInteger(start) && Number.isInteger(end) && start < end);
      if (i > 0) assert.ok(actual[i - 1][1] < start, 'output must be sorted and fully merged');
    }
  }
});
